sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
for (let i = 1; i <= 13; i++) {
    let iString = i.toString();
    var week = "week"+iString;
    const input = api.state[week];
    const templateFields = 'zu_beantragende_gesamtzeit=' + input +  '^kalenderwoche=' + i + '^personalnummer=' +120;
    api.data.create_record_1.execute({
    "table": "x_1663176_bap_antrag",
    "templateFields": templateFields,
    "useSetDisplayValue": false
});
}
}
